input.command:
$paths = @("$HOME\.claude\global-memory", "$HOME\.claude\projects\C--Users-eric-rash-Desktop-DEV\memory", "$HOME\.claude\claude-memory-compiler\daily", "$HOME\.claude\claude-memory-compiler\knowledge")
foreach ($p in $paths) { Write-Output "== $p"; if (Test-Path $p) { Get-ChildItem $p -File -Recurse -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending | Select-Object -First 12 | ForEach-Object { "{0}  {1,8}  {2}" -f $_.LastWriteTime.ToString('yyyy-MM-dd HH:mm'), $_.Length, $_.FullName.Replace($HOME,'~') } } else { "MISSING" } }
Write-Output "== errors log"; $e="$HOME\.claude\global-memory\transcripts\.errors.log"; if (Test-Path $e) { Get-Content $e -Tail 20 } else { "no errors log" }

